import { append, projectConversation, type Session } from '@i-harness/core-session'
import { prepareModelRequest, type LLMRequest, type ModelClient, type PreparedModelRequest } from '@i-harness/llm-seam'

// Local checkpoint text, independently authored rather than parsed/generated by
// the production summary template. This describes only the seeded fixture work.
export const checkpoint = '<compacted-summary>\n## Objective\nContinue the numbered read tasks.\n## Important Details\n'
  + 'Keep the original read results available in the session archive. '.repeat(5)
  + '\n## Work State\nOlder reads completed.\n## Next Move\nAnswer the current human request.\n## Relevant Files\nnumbered.txt\n## Sensitive Instructions\n(none)\n## Tool Work Summary\nCompleted reads are retained in the raw archive.\n</compacted-summary>'

/** A local text-only script. Neutral preparation actually counts the captured
 * request; protocol/cap support remain unknown, with no provider certification.
 * Only this explicitly authored script declares ordinary text output. */
export function summaryModel() {
  const requests: LLMRequest[] = [], preparations: PreparedModelRequest[] = []
  const model: ModelClient = {
    async *stream(request) {
      requests.push(request)
      yield { type: 'text/chunk', text: checkpoint }
      yield { type: 'end' }
    },
    async prepare(request) {
      const prepared = await prepareModelRequest({ stream: model.stream.bind(model) }, request)
      const declare = (candidate: PreparedModelRequest): PreparedModelRequest => Object.freeze({ ...candidate,
        textOutput: Object.freeze({ status: 'allowed' as const, reason: 'ordinary-text' as const }),
        withOutputCap: (cap: number | undefined) => declare(candidate.withOutputCap(cap)),
      })
      const selected = declare(prepared)
      preparations.push(selected)
      return selected
    },
  }
  return { model, requests, preparations }
}

/** Each older task and its completed tool exchange share one physical step.
 * Selection must therefore retain/replace the entire group, including results. */
export function seedSummaryHistory(session: Session, count = 7) {
  const groups = []
  for (let i = 0; i < count; i++) {
    const start = session.events.length
    append(session, { type: 'turn/start' })
    append(session, { type: 'step/start' })
    append(session, { type: 'user/message', text: `${i}: ` + 'word '.repeat(80) })
    append(session, { type: 'tool/call', callId: `old-${i}`, name: 'read', args: { path: `${i}.txt` } })
    append(session, { type: 'assistant/message', text: `Reading ${i}.txt` })
    append(session, { type: 'tool/result', callId: `old-${i}`, name: 'read', output: `${i}: ` + 'result '.repeat(60) })
    append(session, { type: 'step/end' })
    append(session, { type: 'turn/end' })
    groups.push({ start, end: session.events.length, callId: `old-${i}` })
  }
  const projection = projectConversation(session)
  return groups.map(group => ({ ...group, coverage: projection.items
    .filter(item => item.sources.some(source => source.seq !== undefined && source.seq >= group.start && source.seq < group.end))
    .map(item => ({ item: item.ref!, sources: [...new Map([...item.sources, ...item.provenance.evidence]
      .map(source => [JSON.stringify([source.seq, source.part]), { seq: source.seq!, part: source.part }])).values()]
      .sort((a, b) => a.seq - b.seq || Buffer.compare(Buffer.from(a.part), Buffer.from(b.part))) })) }))
}
